#include "neural_net.h"
#include <math.h>
#include <string.h>

/* Linear layer: output = weights * input + biases */
static void linear(const float* input, float* output,
                   const float* weights, const float* biases,
                   size_t input_size, size_t output_size) {
    for (size_t i = 0; i < output_size; i++) {
        output[i] = biases[i];
        for (size_t j = 0; j < input_size; j++) {
            output[i] += weights[i * input_size + j] * input[j];
        }
    }
}

/* ReLU activation */
static __attribute__((unused)) void relu(float* x, size_t size) {
    for (size_t i = 0; i < size; i++) {
        if (x[i] < 0.0f) x[i] = 0.0f;
    }
}

/* Tanh activation */
static void tanh_act(float* x, size_t size) {
    for (size_t i = 0; i < size; i++) {
        x[i] = tanhf(x[i]);
    }
}

/* Clip values to [-1, 1] */
static void clip(float* x, size_t size) {
    for (size_t i = 0; i < size; i++) {
        if      (x[i] >  1.0f) x[i] =  1.0f;
        else if (x[i] < -1.0f) x[i] = -1.0f;
    }
}

