/* Layer 2 biases (4) */
static const float layer2_biases[4] = {
    0.12958871f, 0.13586953f, 0.02800838f, -0.01586081f
};

/* Forward pass through the network */
void forward(const float* input, float* output) {
    float buffer1[96];
    float buffer2[96];
    float* current = buffer1;
    float* next = buffer2;
    float* temp;

    memcpy(current, input, INPUT_DIM * sizeof(float));

    /* Layer 0: 21 -> 96 */
    linear(current, next, layer0_weights, layer0_biases, 21, 96);
    tanh_act(next, 96);
    temp = current; current = next; next = temp;

    /* Layer 1: 96 -> 96 */
    linear(current, next, layer1_weights, layer1_biases, 96, 96);
    tanh_act(next, 96);
    temp = current; current = next; next = temp;

    /* Layer 2: 96 -> 4 */
    linear(current, next, layer2_weights, layer2_biases, 96, 4);
    clip(next, 4);

    memcpy(output, next, OUTPUT_DIM * sizeof(float));
}
